        slack = max(0.0, task.due - state.now - est)
        return base * m * math.exp(-slack / max(k * state.mean_est, 1e-6))
    else:
        age = 1.0 + b * wait / est * min(1.0, state.queue_len / max(q, 1e-6))
        return base * age

